package iq.yasserapps.studio;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.regex.*;import org.json.*;
public final class WindowProfile {
 public static final String PATH="assets/yasserapps-window-profile.json";
 static final Set<String> EDITABLE=new HashSet<>(Arrays.asList("optionalUpdateEnabled","brand","title","body","channelUrl","buttonText","accent","background","logoPng","replacementEnabled"));
 public static JSONObject parse(String s)throws Exception{JSONObject o=new JSONObject(s);if(o.optInt("schema")!=1||!"optional-dialog-v1".equals(o.optString("contract"))||!(o.opt("optionalUpdateEnabled") instanceof Boolean))throw new IOException("Unsupported window profile");if(o.has("replacementEnabled")&&!(o.opt("replacementEnabled") instanceof Boolean))throw new IOException("Invalid replacement flag");validate(o);return o;}
 static void validate(JSONObject o)throws Exception{String logo=o.optString("logoPng","");if(!logo.isEmpty()){if(logo.length()>120000)throw new IOException("Image too large");byte[] b;try{b=java.util.Base64.getDecoder().decode(logo);}catch(IllegalArgumentException e){throw new IOException("Invalid image");}if(b.length<24||b[0]!=(byte)137||b[1]!=80||b[2]!=78||b[3]!=71)throw new IOException("Expected PNG");java.nio.ByteBuffer header=java.nio.ByteBuffer.wrap(b);int width=header.getInt(16),height=header.getInt(20);if(width<1||height<1||width>128||height>128)throw new IOException("Invalid icon dimensions");}for(String k:Arrays.asList("brand","title","body","buttonText")){String v=o.getString(k);if(v.trim().isEmpty()||v.length()>(k.equals("body")?600:80))throw new IOException("Invalid "+k);}
 if(!o.getString("channelUrl").matches("https://t\\.me/[A-Za-z0-9_+\\-]{3,100}"))throw new IOException("Telegram link must be https://t.me/...");for(String k:Arrays.asList("accent","background"))if(!o.getString(k).matches("#[A-Fa-f0-9]{6}"))throw new IOException("Invalid HEX color");}
 public static JSONObject load(File f)throws Exception{return parse(ApkEngine.asset(f,PATH));}
 public static JSONObject edit(JSONObject orig,boolean optional,String brand,String title,String body,String url,String button,String accent,String bg)throws Exception{JSONObject n=parse(orig.toString());n.put("optionalUpdateEnabled",optional);n.put("brand",brand);n.put("title",title);n.put("body",body);n.put("channelUrl",url);n.put("buttonText",button);n.put("accent",accent);n.put("background",bg);validate(n);return n;}
 public static boolean same(JSONObject a,JSONObject b)throws Exception{Set<String> keys=new HashSet<>();a.keys().forEachRemaining(keys::add);b.keys().forEachRemaining(keys::add);for(String k:keys)if(!a.has(k)||!b.has(k)||!String.valueOf(a.get(k)).equals(String.valueOf(b.get(k))))return false;return true;}
 public static JSONObject replacement(JSONObject original,JSONObject preset)throws Exception{JSONObject n=parse(original.toString()),p=parse(preset.toString());if(!"native-brand-v1".equals(n.optString("runtime")))throw new IOException("No compatible brand runtime");for(String k:Arrays.asList("brand","title","body","channelUrl","buttonText","accent","background"))n.put(k,p.getString(k));n.put("logoPng",p.optString("logoPng",""));n.put("replacementEnabled",true);return parse(n.toString());}
 public static void rewrite(File src,File dst,JSONObject n)throws Exception{JSONObject original=load(src);n=parse(n.toString());Set<String> keys=new HashSet<>();original.keys().forEachRemaining(keys::add);n.keys().forEachRemaining(keys::add);for(String k:keys)if(!EDITABLE.contains(k)&&(!original.has(k)||!n.has(k)||!String.valueOf(original.get(k)).equals(String.valueOf(n.get(k)))))throw new IOException("Protected setting changed: "+k);ApkEngine.scan(src);ApkEngine.repack(src,dst,PATH,n.toString(2).getBytes(StandardCharsets.UTF_8));load(dst);}
}